/**
 * Original design and implementation by Gustavo Fior (@gustavo-fior),
 * co-founder Abdul Haidar, and Foglamp Labs. Extracted AS-IS from
 * foglamp-labs/foglamp: apps/web/src/components/marketing/demo/entrance.ts.
 * Licensed under Apache-2.0.
 */
import { type MotionProps, type Variants, stagger } from "motion/react";

// The hero demo's entrance. The chrome frame sits tilted from the first
// paint, and each surface inside it lands on it like a part of a 3D model:
// it starts lifted off the frame's plane and a little further up, then
// settles into place. The inset panel goes first, then the sidebar, then
// the content in the panel. Once the last one has landed, the frame swings
// flat (see Hero). Both files that own a surface share these numbers, so
// the drops match. The lift only reads in 3D, so every ancestor between the
// tilted frame and a surface keeps transform-style: preserve-3d and does
// not clip while the drops run.
//
// The sidebar and the content have no surface of their own. Their pieces
// (nav links, the header, table rows) each make the same drop, one after
// another: the sidebar's pieces land on the chrome, the content's on the
// inset panel. They are Motion variants, so an element only has to be a
// Piece (see piece.tsx) to join in; the wrapper around them (landPieces)
// hands each one its start time and does not move itself.

export const ENTRANCE_EASE: [number, number, number, number] = [
  0.32, 0.72, 0, 1,
];

// The variant names the surfaces, the wrappers, and the pieces share.
export const LIFTED = "lifted";
export const LANDED = "landed";

// Where a surface or a piece starts before it drops: lifted off the plane
// it lands on toward the viewer (z) and a little further up the plane (y),
// in px.
const LIFT = 40;
const DROP = 84;
const DURATION = 1.7;

// The pieces: how far up the plane each starts (it shares LIFT for the
// lift off the plane), how long the drop takes, the gap between one piece
// and the next, and how long after the wrapper's cue the first follows.
const PIECE_DROP = 40;
const PIECE_DURATION = 1.1;
const PIECE_GAP = 0.065;
const PIECE_AFTER = 0.25;

// Seconds after mount that each drop is cued. The chrome's tilt
// is in place by then, and the hero copy is still finishing its rise when
// the sidebar starts, so the two overlap a little.
export const DROP_AT = {
  inset: 0.9,
  sidebar: 1,
  content: 1.8,
} as const;

// How far into the inset surface's drop its colour starts to shift (see
// dropIn). Until then the plate is still the chrome's colour, and it is
// transparent at the start so nothing shows where it hangs above the frame.
const SURFACE_TINT_AT = 0.3;

/** The inset surface's drop, split across two layers because of how the
 * surface appears. It does not simply fade in: in dark mode the surface is
 * only three sRGB levels lighter than the chrome, and a translucent plate
 * blended on the compositor lands on either side of a rounding boundary
 * from frame to frame, which reads as the whole plate flickering while it
 * appears. So the plate fades in (from nothing, so it does not show where
 * it starts above the frame's top edge) while it is still the chrome's
 * own colour, where the blend is exact, and once opaque it shifts colour
 * to its own: an opaque plate rasterises to one exact colour per frame.
 * The shadow does have to fade the whole way, so it sits on a layer of its
 * own (`shadow`); a one-level wobble inside a soft shadow is invisible. The
 * drop is one `transform` string rather than y and z, so the browser runs
 * it off the main thread on the same clock as the fades. Both are nothing
 * under reduced motion. */
export function dropIn(
  delay: number,
  reduce: boolean
): { surface: MotionProps; shadow: MotionProps } {
  if (reduce) return { surface: {}, shadow: {} };
  const transition = { duration: DURATION, ease: ENTRANCE_EASE, delay };
  const split = { ...transition, times: [0, SURFACE_TINT_AT, 1] };
  const surface: Variants = {
    [LIFTED]: {
      opacity: 0,
      backgroundColor: "var(--sidebar)",
      transform: `translateY(${-DROP}px) translateZ(${LIFT}px)`,
    },
    [LANDED]: {
      opacity: [0, 1, 1],
      backgroundColor: ["var(--sidebar)", "var(--sidebar)", "var(--background)"],
      transform: "translateY(0px) translateZ(0px)",
      transition: { ...transition, opacity: split, backgroundColor: split },
    },
  };
  const shadow: Variants = {
    [LIFTED]: { opacity: 0 },
    [LANDED]: { opacity: 1, transition },
  };
  return {
    surface: { initial: LIFTED, animate: LANDED, variants: surface },
    shadow: { initial: LIFTED, animate: LANDED, variants: shadow },
  };
}

/** Motion props for a wrapper whose pieces drop one after another from the
 * given cue, or nothing under reduced motion. The wrapper itself stays put
 * and fully visible; it only passes the variant state and the stagger down
 * to its pieces. The cue's own delay does not reach them, so it is folded
 * into their start. */
export function landPieces(delay: number, reduce: boolean): MotionProps {
  if (reduce) return {};
  const variants: Variants = {
    [LIFTED]: {},
    [LANDED]: {
      transition: {
        delayChildren: stagger(PIECE_GAP, { startDelay: delay + PIECE_AFTER }),
      },
    },
  };
  return { initial: LIFTED, animate: LANDED, variants };
}

/** Variants for one piece: the same drop as a surface. Its wrapper decides
 * when it starts. */
export const PIECE_VARIANTS: Variants = {
  [LIFTED]: { opacity: 0, y: -PIECE_DROP, z: LIFT },
  [LANDED]: {
    opacity: 1,
    y: 0,
    z: 0,
    transition: { duration: PIECE_DURATION, ease: ENTRANCE_EASE },
  },
};

"use client";

/**
 * Original design and implementation by Gustavo Fior (@gustavo-fior),
 * co-founder Abdul Haidar, and Foglamp Labs. Extracted AS-IS from
 * foglamp-labs/foglamp: apps/web/src/components/marketing/demo/piece.tsx.
 * Licensed under Apache-2.0.
 */

import { TableRow } from "../../../ui/table";
import { motion } from "motion/react";
import { createContext, useContext } from "react";

import { PIECE_VARIANTS } from "./entrance";

// One piece of a surface during the entrance (see entrance.ts): it inherits
// the surface's variant state and settles into place on its turn. Once the
// entrance is over, or under reduced motion, a piece that mounts (a tab
// switch) skips its initial state and renders in place like the real app.
// The variants stay on: taking them away makes Motion fall back to the
// piece's recorded initial values, which would hide it.

/** True while the entrance is running. Provided by DemoShell. */
export const EntranceContext = createContext(false);

/** True while the entrance is running. The containers between a wrapper
 * and its pieces use it to stop clipping and keep 3D while the pieces
 * drop (a clipped box flattens everything inside it). */
export function useEntering() {
  return useContext(EntranceContext);
}

const MotionRow = motion.create(TableRow);

/** A block-level piece: a div, or a list item. */
export function Piece({
  as = "div",
  className,
  children,
}: {
  as?: "div" | "li";
  className?: string;
  children: React.ReactNode;
}) {
  const entering = useContext(EntranceContext);
  const Tag = as === "li" ? motion.li : motion.div;
  return (
    <Tag
      variants={PIECE_VARIANTS}
      initial={entering ? undefined : false}
      className={className}
    >
      {children}
    </Tag>
  );
}

/** A table row piece: TableRow with the same behavior. */
export function PieceRow(props: React.ComponentProps<typeof MotionRow>) {
  const entering = useContext(EntranceContext);
  return (
    <MotionRow
      variants={PIECE_VARIANTS}
      initial={entering ? undefined : false}
      {...props}
    />
  );
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/lib/utils.ts; derived here under Apache-2.0.
 */
export { cn } from "cn";

"use client";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import * as React from "react";

import { cn } from "../lib/utils";

type TableContextValue = {
  stickyHeader: boolean;
};

const TableContext = React.createContext<TableContextValue>({
  stickyHeader: false,
});

const alignClass = {
  left: "text-left",
  center: "text-center",
  right: "text-right tabular-nums",
} as const;

type Align = keyof typeof alignClass;

function Table({
  className,
  maxHeight,
  stickyHeader,
  ...props
}: React.ComponentProps<"table"> & {
  /** Cap the table height so the body scrolls internally (enables a sticky header). */
  maxHeight?: number | string;
  /** Pin the header while the body scrolls. Auto-enabled when `maxHeight` is set. */
  stickyHeader?: boolean;
}) {
  const scrollable = maxHeight != null;
  const sticky = stickyHeader ?? scrollable;
  // A sticky header with no internal max-height pins against the *page*
  // scroll — any overflow on this wrapper would create a scroll container
  // that traps `position: sticky`, so the wrapper stays overflow-visible.
  const stickyPage = sticky && !scrollable;
  const containerRef = React.useRef<HTMLDivElement>(null);
  // When the table is wider than its container the horizontal scroll should
  // stay contained to the table, not spill into the page. CSS can't express
  // "overflow only when overflowing", so measure: restore overflow-x-auto
  // only while the table actually overflows (the pinned header is sacrificed
  // in that cramped state — sticky can't survive a scroll container).
  const [overflowing, setOverflowing] = React.useState(false);
  React.useEffect(() => {
    if (!stickyPage) return;
    const el = containerRef.current;
    const table = el?.querySelector("table");
    if (!el || !table) return;
    const measure = () =>
      setOverflowing(table.offsetWidth > el.clientWidth + 1);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    ro.observe(table);
    return () => ro.disconnect();
  }, [stickyPage]);
  return (
    <TableContext.Provider value={{ stickyHeader: sticky }}>
      <div
        ref={containerRef}
        data-slot="table-container"
        className={cn(
          "relative w-full",
          (!stickyPage || overflowing) && "overflow-x-auto",
          scrollable && "overflow-y-auto"
        )}
        style={scrollable ? { maxHeight } : undefined}
      >
        <table
          data-slot="table"
          className={cn(
            "w-full caption-bottom text-sm",
            // Extra right padding on the last column pulls its content in from
            // the screen edge so right-aligned values are easier to scan.
            // Applied here (not on TableHead/TableCell) so it wins over their
            // px-8 and covers any cell component in the last slot.
            "[&_th:last-child]:pr-9 [&_td:last-child]:pr-9",
            className
          )}
          {...props}
        />
      </div>
    </TableContext.Provider>
  );
}

function TableHeader({ className, ...props }: React.ComponentProps<"thead">) {
  const { stickyHeader } = React.useContext(TableContext);
  return (
    <thead
      data-slot="table-header"
      className={cn(
        // Height on the row too: Safari doesn't propagate a thead height down
        // to its tr the way Chromium does.
        "h-13 [&_tr]:h-13",
        // When sticky, a solid page bg so scrolling rows don't show through.
        // The row's border-b doesn't travel with a sticky thead under
        // border-collapse, so draw the bottom rule as an inset shadow on the
        // cells (same color as the body row borders) and drop the row's own
        // border so the two don't stack into a thicker line at rest.
        stickyHeader &&
          "sticky top-0 z-10 bg-background [&_tr]:border-b-0 [&_th]:shadow-[inset_0_-1px_0_0] [&_th]:shadow-border/50 dark:[&_th]:shadow-border/40",
        className
      )}
      {...props}
    />
  );
}

function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("[&_tr:last-child]:border-0", className)}
      {...props}
    />
  );
}

function TableFooter({ className, ...props }: React.ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn(
        "border-t dark:border-[#1E1E1E] border-[#EBEBEB] bg-muted/50 font-medium [&>tr]:last:border-b-0",
        className
      )}
      {...props}
    />
  );
}

function TableRow({
  className,
  interactive,
  onClick,
  onKeyDown,
  tabIndex,
  ...props
}: React.ComponentProps<"tr"> & {
  /** Clickable row: adds hover/pointer, a focus ring, and Enter/Space activation. */
  interactive?: boolean;
}) {
  // Mirror a click on Enter/Space so interactive rows are keyboard-operable.
  const handleKeyDown =
    interactive && onClick
      ? (e: React.KeyboardEvent<HTMLTableRowElement>) => {
          onKeyDown?.(e);
          if (!e.defaultPrevented && (e.key === "Enter" || e.key === " ")) {
            e.preventDefault();
            e.currentTarget.click();
          }
        }
      : onKeyDown;

  return (
    <tr
      data-slot="table-row"
      data-interactive={interactive || undefined}
      tabIndex={interactive ? (tabIndex ?? 0) : tabIndex}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      className={cn(
        "[&_th:last-child]:border-0 border-b dark:border-border/40 border-border/50 data-[state=selected]:bg-muted has-aria-expanded:bg-muted/50",
        "data-interactive:cursor-pointer data-interactive:hover:bg-muted data-interactive:outline-none data-interactive:focus-visible:bg-muted/50 data-interactive:focus-visible:ring-[1.5px] data-interactive:focus-visible:ring-inset data-interactive:focus-visible:ring-ring/50",
        // Hide the hovered row's bottom border and the previous row's (which
        // draws the hovered row's top edge) so the highlight reads as one
        // seamless block instead of a stripe with lines through it. An
        // expanded row (aria-expanded=true) is already one block with the
        // drawer beneath it and keeps its top edge on hover.
        "data-interactive:hover:border-transparent has-[+tr[data-interactive]:not([aria-expanded=true]):hover]:border-transparent",
        className
      )}
      {...props}
    />
  );
}

function TableHead({
  className,
  align,
  ...props
}: Omit<React.ComponentProps<"th">, "align"> & { align?: Align }) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        "text-left align-middle font-medium whitespace-nowrap has-[[role=checkbox]]:pr-0 px-8.25",
        // Vertical column dividers (none on the leftmost cell). More prominent
        // than the body cells to emphasize the header.
        // "border-l border-neutral-200 first:border-l-0 dark:border-neutral-800 [&_tr]:border-b",
        align && alignClass[align],
        className
      )}
      {...props}
    />
  );
}

function TableCell({
  className,
  align,
  ...props
}: Omit<React.ComponentProps<"td">, "align"> & { align?: Align }) {
  return (
    <td
      data-slot="table-cell"
      className={cn(
        "align-middle whitespace-nowrap has-[[role=checkbox]]:pr-0 py-2 px-8.25",
        // Vertical column dividers (none on the leftmost cell).
        // "border-l border-[#EBEBEB] first:border-l-0 dark:border-[#1E1E1E]",
        align && alignClass[align],
        className
      )}
      {...props}
    />
  );
}

function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn(
        "py-2 text-sm text-muted-foreground bg-muted/50 border-t dark:border-[#2A2A2A] border-[#EBEBEB]",
        className
      )}
      {...props}
    />
  );
}

export {
  Table,
  TableHeader,
  TableBody,
  TableFooter,
  TableHead,
  TableRow,
  TableCell,
  TableCaption,
};
